// Involute spur gear (helical when Helix Angle is not 0): module m, z teeth, pressure angle.
fn inv(a) { a.tan() - a }
let alpha = rad(PA);
let rp = m * z / 2.0;
let ra = rp + m;
let rf = rp - 1.25 * m;
let rb = rp * cos(alpha);
let half = PI / (2.0 * z) + inv(alpha);
// half the angular width of a tooth at radius r
fn psi(r, rb, half) { if r <= rb { half } else { half - inv(acos(rb / r)) } }
let flank = [];
let n = 10;
let r0 = if rf > rb { rf } else { rb };
for i in 0..=n { flank.push(r0 + (ra - r0) * i / n); }
let profile = [];
for k in 0..z {
    let c = 2.0 * PI * k / z;
    // root, up the right flank, across the tip, down the left flank
    let pitch = 2.0 * PI / z;
    let root_mid = c - pitch / 2.0;
    profile.push(point(rf * cos(root_mid), rf * sin(root_mid), 0.0));
    if rf < rb { profile.push(point(rf * cos(c - half), rf * sin(c - half), 0.0)); }
    for r in flank { let a = c - psi(r, rb, half); profile.push(point(r * cos(a), r * sin(a), 0.0)); }
    let tip = psi(ra, rb, half);
    for j in 1..4 { let a = c - tip + 2.0 * tip * j / 4; profile.push(point(ra * cos(a), ra * sin(a), 0.0)); }
    let back = flank;
    back.reverse();
    for r in back { let a = c + psi(r, rb, half); profile.push(point(r * cos(a), r * sin(a), 0.0)); }
    if rf < rb { profile.push(point(rf * cos(c + half), rf * sin(c + half), 0.0)); }
}
// sections up the face width, each turned by the helix angle
let turns = if HA == 0.0 { 1 } else { 12 };
let sections = [];
for s in 0..=turns {
    let h = T * s / turns;
    let twist = h * rad(HA).tan() / rp;
    let pts = [];
    for p in profile { pts.push(point(p.x * cos(twist) - p.y * sin(twist), p.x * sin(twist) + p.y * cos(twist), h)); }
    sections.push(polyline(pts, true));
}
gear = cap(loft(sections));
tip_diameter = 2.0 * ra;
pitch_diameter = 2.0 * rp;
